INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM219QPPZ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A pharmaceutical company tests a new headache medication by randomly assigning $500$ volunteers to two groups. Group $1$ receives the medication, and Group $2$ receives a sugar pill that looks identical to the medication. Neither the volunteers nor the researchers administering the pills know which group receives the actual medication. After two weeks, $70\\%$ of Group $1$ reports headache relief compared to $45\\%$ of Group $2$. A statistician confirms the difference is statistically significant. Which of the following is the most appropriate conclusion?', NULL, '[{"key":"A","text":"The medication is effective for the general population because the result is statistically significant."},{"key":"B","text":"The medication likely causes greater headache relief than the placebo among people similar to the volunteers in the study."},{"key":"C","text":"The difference in relief rates is due to the placebo effect, since both groups received pills."},{"key":"D","text":"No conclusion can be drawn because the researchers did not know which group received the medication."}]'::jsonb, 'B', NULL, E'The correct answer is B. The study is a double-blind randomized controlled experiment with a placebo control, which supports a causal conclusion. The statistically significant difference indicates the medication likely causes greater relief than the placebo. However, the conclusion applies to people similar to the volunteers, not necessarily the entire general population, since the volunteers were not randomly selected from the population. Option A overgeneralizes: statistical significance supports causation within the study, but the volunteers may not represent the general population. Option C incorrectly attributes the difference to the placebo effect; the placebo group is the control, and the treatment group showed significantly higher relief, indicating an effect beyond placebo. Option D misunderstands double-blinding: the researchers not knowing group assignments is a design strength that reduces bias, not a weakness.', '{"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}'::jsonb, NULL, 'draft', 1, 105, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22VXWN9', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'mcq', E'A solution is made by mixing chemical $X$ and chemical $Y$ in a ratio of $2:3$ by volume. A second solution mixes the same chemicals in a ratio of $4:1$ by volume. If $100$ mL of the first solution and $150$ mL of the second solution are combined, what fraction of the resulting mixture is chemical $X$?', NULL, '[{"key":"A","text":"$\\\\frac{2}{5}$"},{"key":"B","text":"$\\\\frac{16}{25}$"},{"key":"C","text":"$\\\\frac{3}{5}$"},{"key":"D","text":"$\\\\frac{4}{5}$"}]'::jsonb, 'B', NULL, E'The correct answer is B. In the first solution ($100$ mL, ratio $2:3$), chemical $X$ is $100 \\times \\frac{2}{5} = 40$ mL and chemical $Y$ is $60$ mL. In the second solution ($150$ mL, ratio $4:1$), chemical $X$ is $150 \\times \\frac{4}{5} = 120$ mL and chemical $Y$ is $30$ mL. The combined mixture has $40 + 120 = 160$ mL of $X$ out of $100 + 150 = 250$ mL total, giving a fraction of $\\frac{160}{250} = \\frac{16}{25}$. Option A ($\\frac{2}{5}$) uses only the first solution''s ratio. Option C ($\\frac{3}{5}$) results from adding the ratio parts ($2 + 4 = 6$ out of $10$) without weighting by volume. Option D ($\\frac{4}{5}$) uses only the second solution''s ratio.', '{"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}'::jsonb, NULL, 'draft', 1, 105, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM237TVN9', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'The system of equations below has no solution. What is the value of $k$?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23B50LF', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $h(x) = -2(x + 1)^2 + 8$ models the height, in meters, of a projectile. What is the maximum height reached by the projectile?', NULL, '[{"key":"A","text":"$-1$"},{"key":"B","text":"$2$"},{"key":"C","text":"$8$"},{"key":"D","text":"$-8$"}]'::jsonb, 'C', NULL, E'The correct answer is C. The function is in vertex form $h(x) = a(x - h)^2 + k$, where the vertex is $(-1, 8)$. Because $a = -2 < 0$, the parabola opens downward, so the vertex represents the maximum. The maximum value of $h(x)$ is $8$. Option A ($-1$) gives the $x$-coordinate of the vertex rather than the maximum height. Option B ($2$) uses the absolute value of the leading coefficient. Option D ($-8$) applies a sign error to the maximum value.', '{"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}'::jsonb, NULL, 'draft', 1, 75, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23LURGR', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'The system of equations $y = x^2 - 3x + 2$ and $y = x + 2$ has two solutions. What is the greater value of $x + y$ among the two solutions?', NULL, '[{"key":"A","text":"$2$"},{"key":"B","text":"$4$"},{"key":"C","text":"$6$"},{"key":"D","text":"$10$"}]'::jsonb, 'D', NULL, E'The correct answer is D. Set the equations equal: $x^2 - 3x + 2 = x + 2$, which simplifies to $x^2 - 4x = 0$, or $x(x - 4) = 0$. The solutions are $x = 0$ and $x = 4$. For $x = 0$: $y = 0 + 2 = 2$, so $x + y = 2$. For $x = 4$: $y = 4 + 2 = 6$, so $x + y = 10$. The greater value is $10$. Option A ($2$) is the lesser value of $x + y$, from the solution $(0, 2)$. Option B ($4$) gives only the $x$-coordinate of the second solution without computing $x + y$. Option C ($6$) gives only the $y$-coordinate of the second solution.', '{"D":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"}}'::jsonb, NULL, 'draft', 1, 105, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM241SW4F', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'grid_in', E'What is the value of $x$ in the equation $3x - 9 = 0$?', NULL, '[]'::jsonb, '3', ARRAY['3'], E'To solve $3x - 9 = 0$, add $9$ to both sides to get $3x = 9$. Then divide both sides by $3$ to obtain $x = 3$.', NULL, NULL, 'draft', 1, 45, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM244CW9Z', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'In a right triangle, the hypotenuse has length $20$ and one of the acute angles measures $30°$. What is the length of the side opposite the $30°$ angle?', NULL, '[{"key":"A","text":"$5$"},{"key":"B","text":"$10$"},{"key":"C","text":"$10\\\\sqrt{3}$"},{"key":"D","text":"$20$"}]'::jsonb, 'B', NULL, E'The correct answer is B. In a $30°$-$60°$-$90°$ triangle, the side opposite the $30°$ angle is half the hypotenuse. Therefore, the side opposite $30°$ has length $\\frac{20}{2} = 10$. Equivalently, $\\sin(30°) = \\frac{\\text{opposite}}{20} = \\frac{1}{2}$, giving opposite $= 10$. Option A ($5$) results from an arithmetic error such as dividing $20$ by $4$. Option C ($10\\sqrt{3}$) is the length of the side adjacent to the $30°$ angle (opposite the $60°$ angle), not the requested side. Option D ($20$) is the hypotenuse itself, not the side opposite $30°$.', '{"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}'::jsonb, NULL, 'draft', 1, 75, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24CKIXT', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'grid_in', E'A store increases the price of an item by $20\\%$. During a sale, the new price is then reduced by $30\\%$. The final sale price is what percent of the original price?', NULL, '[]'::jsonb, '84', ARRAY['84'], E'The correct answer is $84$. Let the original price be $100$. After a $20\\%$ increase, the price becomes $100 \\times 1.20 = 120$. After a $30\\%$ decrease from the new price, the price becomes $120 \\times 0.70 = 84$. Therefore the final price is $84\\%$ of the original. A common error is to subtract the percentages ($30\\% - 20\\% = 10\\%$ decrease), which would incorrectly give $90\\%$.', NULL, NULL, 'draft', 1, 105, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24WCVIG', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'What is the sum of the solutions to $2x^2 - 8x + 3 = 0$?', NULL, '[{"key":"A","text":"$3$"},{"key":"B","text":"$4$"},{"key":"C","text":"$\\\\frac{3}{2}$"},{"key":"D","text":"$8$"}]'::jsonb, 'B', NULL, E'The correct answer is B. By Vieta''s formulas, for $ax^2 + bx + c = 0$, the sum of the solutions equals $-\\frac{b}{a}$. Here $a = 2$, $b = -8$, so the sum is $-\\frac{-8}{2} = 4$. Option A ($3$) comes from using the constant term rather than applying Vieta''s formula. Option C ($\\frac{3}{2}$) confuses the sum formula with the product formula $\\frac{c}{a} = \\frac{3}{2}$. Option D ($8$) results from taking $-b = 8$ but neglecting to divide by $a = 2$.', '{"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}'::jsonb, NULL, 'draft', 1, 75, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24Z94E1', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line $p$ has the equation $3x + 5y = 15$. Line $q$ is perpendicular to line $p$ and passes through the point $(6, 1)$. What is the $y$-intercept of line $q$?', NULL, '[{"key":"A","text":"$-9$"},{"key":"B","text":"$-\\\\frac{19}{3}$"},{"key":"C","text":"$\\\\frac{19}{3}$"},{"key":"D","text":"$9$"}]'::jsonb, 'A', NULL, E'The correct answer is A. Rewriting line $p$ in slope-intercept form: $5y = -3x + 15$, so $y = -\\frac{3}{5}x + 3$, and the slope of line $p$ is $-\\frac{3}{5}$. A perpendicular line has slope equal to the negative reciprocal: $\\frac{5}{3}$. Using point-slope form with $(6, 1)$: $y - 1 = \\frac{5}{3}(x - 6)$, so $y = \\frac{5}{3}x - 10 + 1 = \\frac{5}{3}x - 9$. The $y$-intercept is $-9$. Option B results from an arithmetic error when computing $\\frac{5}{3} \\cdot 6$. Option C applies a sign error to the result. Option D uses the parallel slope instead of the perpendicular slope.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}'::jsonb, NULL, 'draft', 1, 105, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25PCEAR', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'The test scores of five students are $72$, $85$, $88$, $91$, and $94$. What is the median score?', NULL, '[{"key":"A","text":"$85$"},{"key":"B","text":"$86$"},{"key":"C","text":"$88$"},{"key":"D","text":"$91$"}]'::jsonb, 'C', NULL, E'The correct answer is C. When the five scores are listed in order ($72, 85, 88, 91, 94$), the median is the middle (third) value, which is $88$. Option A ($85$) is the second value, not the middle value. Option B ($86$) is the mean of the data set ($430 \\div 5 = 86$), which is not the same as the median. Option D ($91$) is the fourth value, not the middle value.', '{"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}'::jsonb, NULL, 'draft', 1, 30, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25PWPRX', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What are the solutions to $x^2 - 5x + 6 = 0$?', NULL, '[{"key":"A","text":"$x = 2$ and $x = 3$"},{"key":"B","text":"$x = -2$ and $x = -3$"},{"key":"C","text":"$x = 1$ and $x = 6$"},{"key":"D","text":"$x = -1$ and $x = -6$"}]'::jsonb, 'A', NULL, E'The correct answer is A. Factor the quadratic: $x^2 - 5x + 6 = (x - 2)(x - 3) = 0$, so $x = 2$ or $x = 3$. Check: $2 + 3 = 5$ (matches the coefficient of $x$ with opposite sign) and $2 \\times 3 = 6$ (matches the constant). Option B ($x = -2$ and $x = -3$) results from a sign error in applying the zero-product property. Option C ($x = 1$ and $x = 6$) uses a factor pair of $6$ that does not sum to $5$. Option D ($x = -1$ and $x = -6$) combines the wrong factor pair with a sign error.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}'::jsonb, NULL, 'draft', 1, 45, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27YTFJ5', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A study finds that students who eat breakfast daily have higher average test scores than students who skip breakfast. The students were not randomly assigned to eat or skip breakfast; instead, the researchers recorded each student''s existing habits. Which of the following is the most appropriate conclusion from this study?', NULL, '[{"key":"A","text":"Eating breakfast causes higher test scores."},{"key":"B","text":"There is an association between eating breakfast and higher test scores, but a causal relationship cannot be established."},{"key":"C","text":"Students who skip breakfast should begin eating breakfast to raise their test scores."},{"key":"D","text":"The study''s results are invalid because the sample was not random."}]'::jsonb, 'B', NULL, E'The correct answer is B. Because the study is observational (students were not randomly assigned to eat or skip breakfast), confounding variables could explain the difference in test scores. The study can establish an association but cannot prove causation. Option A incorrectly claims a causal relationship, which requires random assignment to treatment groups. Option C makes a prescriptive recommendation that relies on a causal interpretation the study does not support. Option D is incorrect because a study can be valid and informative even without random assignment; it simply cannot establish causation.', '{"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}'::jsonb, NULL, 'draft', 1, 75, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM297NVIR', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A researcher surveys a random sample of $400$ adults and finds that $68\\%$ prefer online shopping over in-store shopping. The margin of error is $\\pm 3$ percentage points at a $95\\%$ confidence level. A second researcher surveys a random sample of $1{,}600$ adults from the same population and also finds that $68\\%$ prefer online shopping. Which of the following best describes the margin of error for the second survey at the same confidence level?', NULL, '[{"key":"A","text":"$\\\\pm 0.75$ percentage points"},{"key":"B","text":"$\\\\pm 1.5$ percentage points"},{"key":"C","text":"$\\\\pm 3$ percentage points"},{"key":"D","text":"$\\\\pm 6$ percentage points"}]'::jsonb, 'B', NULL, E'The correct answer is B. The margin of error is inversely proportional to the square root of the sample size. Quadrupling the sample size from $400$ to $1{,}600$ halves the margin of error: $\\frac{3}{\\sqrt{4}} = \\frac{3}{2} = 1.5$ percentage points. Option A ($0.75$) incorrectly divides by $4$ instead of $\\sqrt{4}$. Option C ($3$) assumes the margin of error does not change with sample size. Option D ($6$) incorrectly multiplies by $2$ instead of dividing, suggesting larger samples produce less precision.', '{"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}'::jsonb, NULL, 'draft', 1, 75, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29BH1LY', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'In a school of $800$ students, $60\\%$ participate in at least one extracurricular activity. Of those who participate, $25\\%$ are in more than one activity. How many students are in more than one extracurricular activity?', NULL, '[{"key":"A","text":"$120$"},{"key":"B","text":"$150$"},{"key":"C","text":"$200$"},{"key":"D","text":"$480$"}]'::jsonb, 'A', NULL, E'The correct answer is A. First, $60\\%$ of $800$ students participate: $0.60 \\times 800 = 480$. Of those $480$, $25\\%$ are in more than one activity: $0.25 \\times 480 = 120$. Option B ($150$) results from an arithmetic error. Option C ($200$) comes from taking $25\\%$ of all $800$ students instead of the $480$ who participate. Option D ($480$) is the total number participating, not the number in more than one activity.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}'::jsonb, NULL, 'draft', 1, 75, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BY07MA', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $3(x + 4) - 2x$?', NULL, '[{"key":"A","text":"$x + 12$"},{"key":"B","text":"$x + 4$"},{"key":"C","text":"$5x + 4$"},{"key":"D","text":"$5x + 12$"}]'::jsonb, 'A', NULL, E'The correct answer is A. Distribute the $3$ to get $3x + 12 - 2x$. Combining like terms yields $x + 12$. Option B ($x + 4$) results from failing to distribute the $3$ to the constant $4$, keeping it as $x + 4$. Option C ($5x + 4$) comes from incorrectly adding $3x + 2x = 5x$ instead of subtracting and using $4$ instead of $12$. Option D ($5x + 12$) results from a sign error, adding $3x + 2x$ instead of $3x - 2x$.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}'::jsonb, NULL, 'draft', 1, 45, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CCW7O7', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'In triangle $PQR$, $\\angle P = (2x + 10)°$, $\\angle Q = (3x - 5)°$, and the exterior angle at vertex $R$ measures $(7x - 15)°$. What is the measure, in degrees, of $\\angle P$?', NULL, '[{"key":"A","text":"$10$"},{"key":"B","text":"$25$"},{"key":"C","text":"$30$"},{"key":"D","text":"$55$"}]'::jsonb, 'C', NULL, E'The correct answer is C. By the Exterior Angle Theorem, the exterior angle at $R$ equals the sum of the two non-adjacent interior angles: $(7x - 15) = (2x + 10) + (3x - 5)$. Simplifying the right side gives $5x + 5$, so $7x - 15 = 5x + 5$, which yields $2x = 20$ and $x = 10$. Substituting back, $\\angle P = 2(10) + 10 = 30°$. Option A ($10$) is just the value of $x$, not the angle measure. Option B ($25$) is the measure of $\\angle Q = 3(10) - 5$, not $\\angle P$. Option D ($55$) is the value of the exterior angle $7(10) - 15$, not the requested interior angle.', '{"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}'::jsonb, NULL, 'draft', 1, 105, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CDRFG4', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'grid_in', E'If $\\frac{2x + 1}{3} - \\frac{x - 4}{6} = \\frac{5}{2}$, what is the value of $x$?', NULL, '[]'::jsonb, '3', ARRAY['3'], E'Multiply every term by $6$ (the LCD) to eliminate fractions: $2(2x + 1) - (x - 4) = 3 \\cdot 5$. Distribute: $4x + 2 - x + 4 = 15$, which simplifies to $3x + 6 = 15$. Subtract $6$ from both sides: $3x = 9$. Divide by $3$: $x = 3$. Verification: $\\frac{2(3)+1}{3} - \\frac{3-4}{6} = \\frac{7}{3} + \\frac{1}{6} = \\frac{14}{6} + \\frac{1}{6} = \\frac{15}{6} = \\frac{5}{2}$.', NULL, NULL, 'draft', 1, 105, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DAWA3F', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'The function $f$ is defined by $f(x) = -3x + 12$. If $f(a) = 0$, what is the value of $f(2a)$?', NULL, '[{"key":"A","text":"$-24$"},{"key":"B","text":"$-12$"},{"key":"C","text":"$0$"},{"key":"D","text":"$12$"}]'::jsonb, 'B', NULL, E'The correct answer is B. First, find $a$ by setting $f(a) = 0$: $-3a + 12 = 0$, so $a = 4$. Then $2a = 8$, and $f(8) = -3(8) + 12 = -24 + 12 = -12$. Option A results from computing $-3(8) = -24$ but forgetting to add $12$. Option C incorrectly assumes that $f(2a) = 0$ because $f(a) = 0$. Option D results from a sign error, computing $3(8) - 12 = 12$.', '{"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}'::jsonb, NULL, 'draft', 1, 75, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EP3QY6', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'grid_in', E'A square has a perimeter of $24$. What is the area of the square?', NULL, '[]'::jsonb, '36', ARRAY['36'], E'The perimeter of a square is $4s$, where $s$ is the side length. So $4s = 24$ and $s = 6$. The area is $s^2 = 6^2 = 36$. A common error is to divide the perimeter by $2$ instead of $4$, giving $s = 12$ and an incorrect area of $144$.', NULL, NULL, 'draft', 1, 60, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EWLER9', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $f$ is defined by $f(x) = a \\cdot b^x$, where $a$ and $b$ are positive constants. If $f(1) = 12$ and $f(3) = 108$, what is the value of $f(0)$?', NULL, '[{"key":"A","text":"$1$"},{"key":"B","text":"$4$"},{"key":"C","text":"$9$"},{"key":"D","text":"$36$"}]'::jsonb, 'B', NULL, E'The correct answer is B. From $f(1) = ab = 12$ and $f(3) = ab^3 = 108$, divide the second equation by the first: $\\frac{ab^3}{ab} = b^2 = \\frac{108}{12} = 9$. Since $b > 0$, $b = 3$. Substituting back: $a(3) = 12$, so $a = 4$. Therefore $f(0) = a \\cdot b^0 = a \\cdot 1 = 4$. Option A ($1$) confuses $f(0)$ with $b^0 = 1$, forgetting to multiply by $a$. Option C ($9$) gives the value of $b^2$ rather than $a$, stopping at an intermediate result. Option D ($36$) results from computing $f(1) \\cdot b = 12 \\cdot 3 = 36$, which is $f(2)$ rather than $f(0)$.', '{"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}'::jsonb, NULL, 'draft', 1, 105, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EX1W0J', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A car travels $150$ miles using $5$ gallons of gasoline. At this same rate, how many gallons of gasoline would the car need to travel $420$ miles?', NULL, '[{"key":"A","text":"$12$"},{"key":"B","text":"$14$"},{"key":"C","text":"$15$"},{"key":"D","text":"$21$"}]'::jsonb, 'B', NULL, E'The correct answer is B. The car''s rate is $\\frac{150}{5} = 30$ miles per gallon. To find the gallons needed for $420$ miles, divide: $\\frac{420}{30} = 14$ gallons. Option A ($12$) results from an arithmetic error when dividing. Option C ($15$) comes from incorrectly setting up the proportion. Option D ($21$) results from misapplying the rate, such as using $20$ miles per gallon.', '{"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}'::jsonb, NULL, 'draft', 1, 75, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2F25102', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a radius of $7$. What is the area of the circle?', NULL, '[{"key":"A","text":"$7\\\\pi$"},{"key":"B","text":"$14\\\\pi$"},{"key":"C","text":"$49$"},{"key":"D","text":"$49\\\\pi$"}]'::jsonb, 'D', NULL, E'The correct answer is D. The area of a circle is $A = \\pi r^2 = \\pi(7)^2 = 49\\pi$. Option A ($7\\pi$) results from computing $\\pi r$ instead of $\\pi r^2$, omitting the squaring step. Option B ($14\\pi$) is the circumference ($2\\pi r$), not the area. Option C ($49$) correctly squares the radius but omits the factor of $\\pi$.', '{"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"correct","error_taxonomy":null}}'::jsonb, NULL, 'draft', 1, 45, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FJSCU2', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $g(x) = x^2 - 6x + 9$ can be rewritten as $g(x) = (x - 3)^2$. What is the minimum value of $g(x)$?', NULL, '[{"key":"A","text":"$0$"},{"key":"B","text":"$3$"},{"key":"C","text":"$6$"},{"key":"D","text":"$9$"}]'::jsonb, 'A', NULL, E'The correct answer is A. Since $g(x) = (x - 3)^2$, the expression is a perfect square and is always greater than or equal to $0$. The minimum value $0$ occurs when $x = 3$. Option B ($3$) confuses the $x$-value where the minimum occurs with the minimum value itself. Option C ($6$) uses the coefficient of $x$ from the original form. Option D ($9$) uses the constant term from the original expanded form, not recognizing that the vertex value is $0$.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}'::jsonb, NULL, 'draft', 1, 45, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FMR8BT', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'Two angles form a linear pair. If one of the angles measures $125°$, what is the measure, in degrees, of the other angle?', NULL, '[{"key":"A","text":"$55$"},{"key":"B","text":"$65$"},{"key":"C","text":"$125$"},{"key":"D","text":"$235$"}]'::jsonb, 'A', NULL, E'The correct answer is A. A linear pair of angles are supplementary, meaning they sum to $180°$. Therefore, the other angle measures $180° - 125° = 55°$. Option B ($65$) results from an arithmetic error in the subtraction. Option C ($125$) incorrectly assumes a linear pair consists of two equal angles. Option D ($235$) results from subtracting from $360°$ instead of $180°$.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}'::jsonb, NULL, 'draft', 1, 45, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GKI0KQ', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'In the $xy$-plane, line $m$ passes through $(2, 7)$ and $(5, 1)$. Line $n$ passes through $(-3, 4)$ and is parallel to line $m$. What is the $x$-intercept of line $n$?', NULL, '[{"key":"A","text":"$-1$"},{"key":"B","text":"$-\\\\frac{1}{2}$"},{"key":"C","text":"$\\\\frac{1}{2}$"},{"key":"D","text":"$1$"}]'::jsonb, 'A', NULL, E'The correct answer is A. The slope of line $m$ is $\\frac{1 - 7}{5 - 2} = \\frac{-6}{3} = -2$. Since line $n$ is parallel, it also has slope $-2$. Using point-slope form with $(-3, 4)$: $y - 4 = -2(x + 3)$, so $y = -2x - 6 + 4 = -2x - 2$. The $x$-intercept occurs when $y = 0$: $0 = -2x - 2$, giving $x = -1$. Option B results from an arithmetic slip in solving $-2x - 2 = 0$. Option C applies a sign error to the final answer. Option D finds $x = 1$ by dropping the negative sign when computing the slope.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}'::jsonb, NULL, 'draft', 1, 110, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GVUOAU', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'For what value of $k$ does the inequality $k(x - 3) + 2 > 2(x + 1)$ have no solution?', NULL, '[{"key":"A","text":"$-2$"},{"key":"B","text":"$0$"},{"key":"C","text":"$2$"},{"key":"D","text":"$6$"}]'::jsonb, 'C', NULL, E'The correct answer is C. Expanding the left side gives $kx - 3k + 2 > 2x + 2$. Rearranging: $(k - 2)x > 3k$. For this inequality to have no solution, the coefficient of $x$ must be $0$ while the right side is positive. Setting $k - 2 = 0$ gives $k = 2$. Substituting $k = 2$ yields $0 \\cdot x > 6$, which simplifies to $0 > 6$, a contradiction for all $x$, confirming no solution exists. Option A ($k = -2$) results from a sign error when setting $k - 2 = 0$. Option B ($k = 0$) reflects a conceptual misunderstanding, setting $k = 0$ instead of analyzing the coefficient of $x$. Option D ($k = 6$) results from incorrectly setting $3k = k - 2$ and solving.', '{"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}'::jsonb, NULL, 'draft', 1, 100, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2H1WM53', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $\\frac{x^2 - 9}{x^2 - 6x + 9}$?', NULL, '[{"key":"A","text":"$\\\\frac{x + 3}{x - 3}$"},{"key":"B","text":"$\\\\frac{x - 3}{x + 3}$"},{"key":"C","text":"$\\\\frac{x + 3}{x + 3}$"},{"key":"D","text":"$\\\\frac{3}{x - 3}$"}]'::jsonb, 'A', NULL, E'The correct answer is A. Factor the numerator as a difference of squares: $x^2 - 9 = (x + 3)(x - 3)$. Factor the denominator as a perfect square trinomial: $x^2 - 6x + 9 = (x - 3)^2$. Canceling one common factor of $(x - 3)$ gives $\\frac{x + 3}{x - 3}$. Option B reverses which factor remains after cancellation, reflecting a misunderstanding of the factored forms. Option C incorrectly factors the denominator as $(x + 3)^2$ instead of $(x - 3)^2$. Option D results from incorrectly canceling $x$ terms rather than the full binomial factor.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}'::jsonb, NULL, 'draft', 1, 75, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2H8DAQF', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'grid_in', E'Two chords intersect at a point inside a circle. One chord is divided into segments of lengths $3$ and $8$. The other chord is divided into segments of lengths $4$ and $x$. What is the value of $x$?', NULL, '[]'::jsonb, '6', ARRAY['6'], E'When two chords intersect inside a circle, the products of their segments are equal. This gives $3 \\times 8 = 4 \\times x$, so $24 = 4x$ and $x = 6$. A common error is to set up an additive relationship ($3 + 8 = 4 + x$, yielding $x = 7$) instead of the multiplicative one required by the intersecting chords theorem. Another error is to reverse the relationship and compute $x = \\frac{4 \\times 3}{8} = 1.5$.', NULL, NULL, 'draft', 1, 120, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2I48WTZ', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'The linear function $g$ is defined for all real numbers. The table below shows selected values of $g$.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JNRQ8F', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'grid_in', E'A trapezoid has parallel bases of lengths $10$ and $14$ and a height of $6$. What is the area of the trapezoid?', NULL, '[]'::jsonb, '72', ARRAY['72'], E'The area of a trapezoid is $A = \\frac{1}{2}(b_1 + b_2)h$. Substituting the given values: $A = \\frac{1}{2}(10 + 14)(6) = \\frac{1}{2}(24)(6) = 72$. A common error is to omit the factor of $\\frac{1}{2}$, giving $144$. Another error is to multiply only one base by the height, yielding $60$ or $84$.', NULL, NULL, 'draft', 1, 90, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LUA7KI', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $ABC$, the exterior angle at vertex $C$ measures $130°$. If $\\angle A = 55°$, what is the measure, in degrees, of $\\angle B$?', NULL, '[{"key":"A","text":"$50$"},{"key":"B","text":"$55$"},{"key":"C","text":"$75$"},{"key":"D","text":"$125$"}]'::jsonb, 'C', NULL, E'The correct answer is C. By the Exterior Angle Theorem, an exterior angle of a triangle equals the sum of the two non-adjacent interior angles. So the exterior angle at $C$ equals $\\angle A + \\angle B$: $130° = 55° + \\angle B$, which gives $\\angle B = 75°$. Option A ($50$) comes from incorrectly computing $180° - 130°$, confusing the exterior angle with the interior angle at $C$. Option B ($55$) is simply the given measure of $\\angle A$, not $\\angle B$. Option D ($125$) results from computing $180° - 55°$, which finds the supplement of $\\angle A$ rather than using the exterior angle relationship.', '{"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}'::jsonb, NULL, 'draft', 1, 75, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MEGL5X', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which value of $x$ satisfies the inequality $4x + 3 \\leq 15$?', NULL, '[{"key":"A","text":"$1$"},{"key":"B","text":"$4$"},{"key":"C","text":"$5$"},{"key":"D","text":"$6$"}]'::jsonb, 'A', NULL, E'The correct answer is A. Substituting $x = 1$ gives $4(1) + 3 = 7$, and $7 \\leq 15$ is true. Solving the inequality algebraically: subtract $3$ from both sides to get $4x \\leq 12$, then divide by $4$ to get $x \\leq 3$. Only $x = 1$ satisfies this condition. Option B ($x = 4$) gives $4(4) + 3 = 19 > 15$, which violates the inequality. Option C ($x = 5$) gives $23 > 15$, and option D ($x = 6$) gives $27 > 15$, both of which also fail.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}'::jsonb, NULL, 'draft', 1, 60, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MO8YHY', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A researcher models the relationship between the number of hours of sunlight per day ($x$) and the height of a plant in centimeters ($y$) using the equation $y = 1.4x + 3.2$. A second model is $y = 0.12x^2 + 0.2x + 4$. At $x = 10$ hours, a plant is observed to have a height of $18.5$ cm. Which of the following correctly gives the residual at $x = 10$ for each model?', NULL, '[{"key":"A","text":"Model 1 residual: $1.3$; Model 2 residual: $0.5$"},{"key":"B","text":"Model 1 residual: $-1.3$; Model 2 residual: $-0.5$"},{"key":"C","text":"Model 1 residual: $1.3$; Model 2 residual: $-0.5$"},{"key":"D","text":"Model 1 residual: $0.5$; Model 2 residual: $1.3$"}]'::jsonb, 'A', NULL, E'The correct answer is A. A residual is calculated as actual minus predicted. Model 1 predicts $y = 1.4(10) + 3.2 = 14 + 3.2 = 17.2$. The residual is $18.5 - 17.2 = 1.3$. Model 2 predicts $y = 0.12(100) + 0.2(10) + 4 = 12 + 2 + 4 = 18$. The residual is $18.5 - 18 = 0.5$. Both residuals are positive because the actual value exceeds both predictions. Option B reverses the sign by computing predicted minus actual. Option C correctly computes Model 1 but reverses the sign for Model 2. Option D swaps the residual values between the two models.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}'::jsonb, NULL, 'draft', 1, 105, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MYDTD7', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'A plumber charges a flat fee of $\\$50$ plus $\\$30$ per hour. Which function $f(h)$ gives the total charge, in dollars, for $h$ hours of work?', NULL, '[{"key":"A","text":"$f(h) = 30h + 50$"},{"key":"B","text":"$f(h) = 50h + 30$"},{"key":"C","text":"$f(h) = 80h$"},{"key":"D","text":"$f(h) = 30h - 50$"}]'::jsonb, 'A', NULL, E'The correct answer is A. The total charge consists of a flat fee of $\\$50$ (constant term) plus $\\$30$ per hour (rate times $h$), giving $f(h) = 30h + 50$. Option B reverses the rate and the flat fee. Option C adds the two values and treats the result as a single hourly rate, losing the constant. Option D incorrectly subtracts the flat fee.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}'::jsonb, NULL, 'draft', 1, 30, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2N1YVT4', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A scatterplot shows the relationship between the number of hours studied and test scores for $10$ students. The data show that as the number of hours studied increases, the test scores tend to increase. Which of the following best describes the association shown in the scatterplot?', NULL, '[{"key":"A","text":"Positive linear association"},{"key":"B","text":"Negative linear association"},{"key":"C","text":"No association"},{"key":"D","text":"Nonlinear association"}]'::jsonb, 'A', NULL, E'The correct answer is A. When one variable increases and the other also tends to increase, the association is positive. A trend where test scores increase as hours studied increase, without curvature mentioned, is best described as a positive linear association. Option B is wrong because a negative association means one variable decreases as the other increases. Option C is wrong because a clear trend is described. Option D is wrong because no curvature is indicated in the data.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}'::jsonb, NULL, 'draft', 1, 30, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2N5MLVU', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A bag contains $3$ red marbles, $5$ blue marbles, and $2$ green marbles. If one marble is selected at random, what is the probability that it is blue?', NULL, '[{"key":"A","text":"$\\\\frac{1}{5}$"},{"key":"B","text":"$\\\\frac{3}{10}$"},{"key":"C","text":"$\\\\frac{1}{2}$"},{"key":"D","text":"$\\\\frac{3}{5}$"}]'::jsonb, 'C', NULL, E'The correct answer is C. The total number of marbles is $3 + 5 + 2 = 10$. The probability of selecting a blue marble is $\\frac{5}{10} = \\frac{1}{2}$. Option A ($\\frac{1}{5}$) results from dividing $2$ by $10$ instead of $5$ by $10$. Option B ($\\frac{3}{10}$) comes from using the count of red marbles rather than blue. Option D ($\\frac{3}{5}$) results from incorrectly adding only $5 + 3 = 8$ marbles as the total and simplifying $\\frac{5}{8}$ incorrectly, or from a conceptual error in forming the ratio.', '{"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}'::jsonb, NULL, 'draft', 1, 45, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NEGEOW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'A polling organization surveys a random sample of $600$ registered voters and reports that $47\\%$ support Candidate A, with a margin of error of $\\pm 4$ percentage points at a $95\\%$ confidence level. A rival polling organization claims that, based on its own random sample, Candidate A has majority support (more than $50\\%$). Which of the following is the best conclusion?', NULL, '[{"key":"A","text":"The first poll''s result proves that Candidate A does not have majority support."},{"key":"B","text":"The rival organization''s claim is necessarily wrong because $47\\\\%$ is less than $50\\\\%$."},{"key":"C","text":"The first poll''s confidence interval includes $50\\\\%$, so the data are consistent with the possibility that Candidate A has majority support."},{"key":"D","text":"Because the margin of error is $\\\\pm 4$ percentage points, exactly $51\\\\%$ of voters support Candidate A."}]'::jsonb, 'C', NULL, E'The correct answer is C. The $95\\%$ confidence interval from the first poll is $47\\% \\pm 4\\%$, or $[43\\%, 51\\%]$. Since $50\\%$ falls within this interval, the poll''s data do not rule out the possibility that Candidate A has majority support. Option A overstates the conclusion: the interval includes values above $50\\%$, so the poll does not prove a lack of majority support. Option B makes the same error, treating the sample statistic as exact. Option D incorrectly interprets the margin of error as pinpointing a specific value rather than defining a range of plausible values.', '{"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}'::jsonb, NULL, 'draft', 1, 90, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OMJ6GP', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A standard deck of $52$ playing cards contains $4$ suits, each with $13$ cards. Two cards are drawn at random without replacement. Given that the first card drawn is a heart, what is the probability that the second card drawn is also a heart?', NULL, '[{"key":"A","text":"$\\\\frac{1}{4}$"},{"key":"B","text":"$\\\\frac{12}{51}$"},{"key":"C","text":"$\\\\frac{13}{52}$"},{"key":"D","text":"$\\\\frac{12}{52}$"}]'::jsonb, 'B', NULL, E'The correct answer is B. After one heart is drawn, there are $12$ hearts remaining among $51$ total cards. The conditional probability is $\\frac{12}{51}$. Option A ($\\frac{1}{4}$) treats the draws as independent, ignoring that the first card was not replaced. Option C ($\\frac{13}{52}$) gives the probability of drawing a heart on the first draw, not the conditional probability for the second. Option D ($\\frac{12}{52}$) correctly reduces the hearts to $12$ but fails to reduce the total from $52$ to $51$.', '{"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}'::jsonb, NULL, 'draft', 1, 75, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PGZK7I', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'In a right triangle, the two legs have lengths $a$ and $b$, where $a = 2b$. If the hypotenuse has length $10\\sqrt{5}$, what is the area of the triangle?', NULL, '[{"key":"A","text":"$10$"},{"key":"B","text":"$50$"},{"key":"C","text":"$100$"},{"key":"D","text":"$200$"}]'::jsonb, 'C', NULL, E'The correct answer is C. By the Pythagorean theorem, $a^2 + b^2 = (10\\sqrt{5})^2 = 500$. Substituting $a = 2b$ gives $(2b)^2 + b^2 = 500$, so $4b^2 + b^2 = 500$ and $5b^2 = 500$. Therefore $b^2 = 100$ and $b = 10$, which gives $a = 20$. The area is $\\frac{1}{2}ab = \\frac{1}{2}(20)(10) = 100$. Option A ($10$) is just the value of $b$, not the area. Option B ($50$) results from computing $\\frac{1}{2}b^2 = \\frac{1}{2}(100)$, using $b$ for both legs. Option D ($200$) comes from computing $ab = (20)(10)$ without the factor of $\\frac{1}{2}$.', '{"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}'::jsonb, NULL, 'draft', 1, 105, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q490AL', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'A medical test for a certain condition has a $95\\%$ true positive rate (sensitivity) and a $90\\%$ true negative rate (specificity). In a population where $2\\%$ of people have the condition, a person is selected at random and tests positive. What is the probability, to the nearest hundredth, that this person actually has the condition?', NULL, '[{"key":"A","text":"$0.16$"},{"key":"B","text":"$0.50$"},{"key":"C","text":"$0.90$"},{"key":"D","text":"$0.95$"}]'::jsonb, 'A', NULL, E'The correct answer is A. Using Bayes'' theorem, $P(\\text{condition} \\mid \\text{positive}) = \\frac{P(\\text{positive} \\mid \\text{condition}) \\cdot P(\\text{condition})}{P(\\text{positive})}$. The probability of testing positive is $P(\\text{positive}) = (0.95)(0.02) + (0.10)(0.98) = 0.019 + 0.098 = 0.117$. Therefore, $P(\\text{condition} \\mid \\text{positive}) = \\frac{0.019}{0.117} \\approx 0.16$. Option B ($0.50$) reflects a guess that a positive test means a coin-flip chance, ignoring the low base rate. Option C ($0.90$) confuses the specificity with the answer. Option D ($0.95$) mistakes the sensitivity (true positive rate) for the positive predictive value, ignoring the base rate entirely.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}'::jsonb, NULL, 'draft', 1, 120, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q4D7NH', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A researcher wants to determine whether a new fertilizer increases tomato plant growth. She applies the fertilizer to $30$ randomly selected plants and does not apply it to another $30$ randomly selected plants, keeping all other growing conditions the same. This study is best described as which of the following?', NULL, '[{"key":"A","text":"An observational study"},{"key":"B","text":"A survey"},{"key":"C","text":"An experiment"},{"key":"D","text":"A census"}]'::jsonb, 'C', NULL, E'The correct answer is C. The researcher randomly assigns plants to a treatment group (fertilizer) and a control group (no fertilizer) while keeping other conditions the same. This is the defining characteristic of an experiment: the researcher imposes a treatment and uses random assignment. Option A is incorrect because in an observational study the researcher does not impose a treatment. Option B describes a data-collection method that asks questions of participants, which does not apply here. Option D refers to collecting data from every member of a population, not testing a treatment.', '{"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}'::jsonb, NULL, 'draft', 1, 45, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QXMEEI', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'A right triangle has legs of lengths $6$ and $8$. What is the length of the hypotenuse?', NULL, '[{"key":"A","text":"$10$"},{"key":"B","text":"$14$"},{"key":"C","text":"$48$"},{"key":"D","text":"$100$"}]'::jsonb, 'A', NULL, E'The correct answer is A. By the Pythagorean theorem, $c^2 = a^2 + b^2 = 6^2 + 8^2 = 36 + 64 = 100$, so $c = \\sqrt{100} = 10$. Option B ($14$) results from adding the legs ($6 + 8$) instead of using the Pythagorean theorem. Option C ($48$) comes from multiplying the legs ($6 \\times 8$). Option D ($100$) is the value of $c^2$ before taking the square root.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}'::jsonb, NULL, 'draft', 1, 45, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QYGH8I', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'A data set contains the values $3, 5, 7, 7, 8, 10, 12$. If the value $12$ is replaced with $20$, which of the following measures will change?', NULL, '[{"key":"A","text":"Median only"},{"key":"B","text":"Mean only"},{"key":"C","text":"Mode only"},{"key":"D","text":"Both mean and median"}]'::jsonb, 'B', NULL, E'The correct answer is B. The original data set $3, 5, 7, 7, 8, 10, 12$ has a median of $7$ (the 4th value of 7 values), a mode of $7$, and a mean of $\\frac{52}{7} \\approx 7.43$. Replacing $12$ with $20$ gives $3, 5, 7, 7, 8, 10, 20$. The median is still $7$ (the 4th value), and the mode is still $7$. The mean changes to $\\frac{60}{7} \\approx 8.57$. Only the mean changes. Option A is wrong because the median does not change. Option C is wrong because the mode does not change. Option D is wrong because only the mean changes.', '{"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}'::jsonb, NULL, 'draft', 1, 75, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2R7VGFB', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'mcq', E'The mean of a set of $10$ numbers is $18$. When one number is removed from the set, the mean of the remaining $9$ numbers is $17$. What is the value of the number that was removed?', NULL, '[{"key":"A","text":"$1$"},{"key":"B","text":"$9$"},{"key":"C","text":"$17$"},{"key":"D","text":"$27$"}]'::jsonb, 'D', NULL, E'The correct answer is D. The sum of the original $10$ numbers is $10 \\times 18 = 180$. After removing one number, the sum of the remaining $9$ numbers is $9 \\times 17 = 153$. The removed number is $180 - 153 = 27$. Option A ($1$) results from subtracting the means ($18 - 17 = 1$) instead of subtracting the sums. Option B ($9$) comes from incomplete reasoning, such as dividing the difference incorrectly. Option C ($17$) confuses the new mean with the removed value.', '{"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"correct","error_taxonomy":null}}'::jsonb, NULL, 'draft', 1, 90, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2S1KOTV', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'grid_in', E'A shirt originally costs $\\$40$. If the shirt is on sale for $15\\%$ off, what is the sale price, in dollars?', NULL, '[]'::jsonb, '34', ARRAY['34'], E'The correct answer is $34$. The discount is $15\\%$ of $\\$40$: $0.15 \\times 40 = 6$ dollars. The sale price is $40 - 6 = 34$ dollars.', NULL, NULL, 'draft', 1, 45, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2S1LF2Z', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'grid_in', E'The equation of a circle in the $xy$-plane is $(x - 3)^2 + (y + 2)^2 = 36$. What is the diameter of the circle?', NULL, '[]'::jsonb, '12', ARRAY['12'], E'The standard form of a circle is $(x - h)^2 + (y - k)^2 = r^2$, where $(h, k)$ is the center and $r$ is the radius. From the given equation, $r^2 = 36$, so $r = 6$. The diameter is $2r = 2(6) = 12$. A common error is to give the radius ($6$) instead of the diameter, or to confuse $r^2 = 36$ with $r = 36$.', NULL, NULL, 'draft', 1, 90, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2S493EK', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'grid_in', E'A movie theater sold a total of $200$ tickets for a showing. Adult tickets cost $\\$12$ each and child tickets cost $\\$8$ each. If the total revenue from ticket sales was $\\$2{,}000$, how many adult tickets were sold?', NULL, '[]'::jsonb, '100', ARRAY['100'], E'The correct answer is $100$. Let $a$ represent the number of adult tickets and $c$ represent the number of child tickets. The system of equations is $a + c = 200$ and $12a + 8c = 2000$. From the first equation, $c = 200 - a$. Substituting into the second equation gives $12a + 8(200 - a) = 2000$, which simplifies to $12a + 1600 - 8a = 2000$. Combining like terms yields $4a = 400$, so $a = 100$. Verification: $100$ adult tickets and $100$ child tickets produce revenue of $100(12) + 100(8) = 1200 + 800 = 2000$.', NULL, NULL, 'draft', 1, 90, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SXJLRE', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of $200$ voters in a city found that $56\\%$ support a proposed park renovation. The margin of error for the survey is $\\pm 4$ percentage points. Which of the following is a plausible value for the true percentage of all voters in the city who support the renovation?', NULL, '[{"key":"A","text":"$50\\\\%$"},{"key":"B","text":"$54\\\\%$"},{"key":"C","text":"$61\\\\%$"},{"key":"D","text":"$63\\\\%$"}]'::jsonb, 'B', NULL, E'The correct answer is B. The confidence interval is $56\\% \\pm 4\\%$, which gives a range of $52\\%$ to $60\\%$. A plausible value for the true percentage must fall within this interval. $54\\%$ falls within $[52\\%, 60\\%]$. Option A ($50\\%$) is below the lower bound of $52\\%$. Option C ($61\\%$) is just above the upper bound of $60\\%$. Option D ($63\\%$) is well above the interval.', '{"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}'::jsonb, NULL, 'draft', 1, 45, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TF8M5L', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'Which of the following is equivalent to $(x^2 - 4x + 4)(x^2 + 4x + 4)$?', NULL, '[{"key":"A","text":"$x^4 - 16$"},{"key":"B","text":"$x^4 + 8x^2 + 16$"},{"key":"C","text":"$x^4 - 8x^2 + 16$"},{"key":"D","text":"$x^4 - 16x^2 + 16$"}]'::jsonb, 'C', NULL, E'The correct answer is C. Recognize that $x^2 - 4x + 4 = (x - 2)^2$ and $x^2 + 4x + 4 = (x + 2)^2$. Then $(x - 2)^2(x + 2)^2 = [(x - 2)(x + 2)]^2 = (x^2 - 4)^2$. Expanding: $(x^2 - 4)^2 = x^4 - 2(4)(x^2) + 16 = x^4 - 8x^2 + 16$. Option A ($x^4 - 16$) treats the product as a simple difference of squares $(x^2)^2 - 4^2$ without squaring. Option B ($x^4 + 8x^2 + 16$) applies a sign error, using $+8x^2$ instead of $-8x^2$. Option D ($x^4 - 16x^2 + 16$) results from an arithmetic slip in computing $2(4) = 16$ instead of the correct middle term coefficient $8$.', '{"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}'::jsonb, NULL, 'draft', 1, 105, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TYJ15R', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A gym charges a monthly membership fee of $\\$30$ plus $\\$5$ per fitness class attended. If a member wants to spend no more than $\\$75$ in a month, what is the maximum number of fitness classes the member can attend?', NULL, '[{"key":"A","text":"$8$"},{"key":"B","text":"$9$"},{"key":"C","text":"$10$"},{"key":"D","text":"$15$"}]'::jsonb, 'B', NULL, E'The correct answer is B. The total cost is $30 + 5c$, where $c$ is the number of classes. Setting up the inequality $30 + 5c \\leq 75$ and subtracting $30$ from both sides gives $5c \\leq 45$. Dividing both sides by $5$ yields $c \\leq 9$, so the maximum number of classes is $9$. Option A ($8$) results from incorrectly using a strict inequality ($<$) and rounding down. Option C ($10$) comes from an arithmetic error such as computing $75 - 30 = 45$ and then dividing by $4.5$ instead of $5$. Option D ($15$) results from ignoring the $\\$30$ membership fee entirely and computing $75 \\div 5 = 15$.', '{"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}'::jsonb, NULL, 'draft', 1, 75, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2V2NNJV', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'The equation $5x - 2y = 20$ represents a line in the $xy$-plane. What is the $y$-intercept of this line?', NULL, '[{"key":"A","text":"$-10$"},{"key":"B","text":"$-4$"},{"key":"C","text":"$4$"},{"key":"D","text":"$10$"}]'::jsonb, 'A', NULL, E'The correct answer is A. The $y$-intercept occurs when $x = 0$. Substituting $x = 0$ into $5(0) - 2y = 20$ gives $-2y = 20$, so $y = -10$. Option B results from dividing $20$ by $5$ to find the $x$-intercept. Option C comes from a sign error when dividing by $-2$. Option D is obtained by ignoring the negative sign on the $2y$ term.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}'::jsonb, NULL, 'draft', 1, 60, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2X8UIK1', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A recipe calls for $2$ cups of flour to make $24$ cookies. How many cups of flour are needed to make $60$ cookies?', NULL, '[{"key":"A","text":"$3$"},{"key":"B","text":"$4$"},{"key":"C","text":"$5$"},{"key":"D","text":"$6$"}]'::jsonb, 'C', NULL, E'The correct answer is C. The ratio of flour to cookies is $\\frac{2}{24} = \\frac{1}{12}$, so each cookie requires $\\frac{1}{12}$ cup of flour. For $60$ cookies: $60 \\times \\frac{1}{12} = 5$ cups. Option A ($3$) results from an arithmetic error in the proportion. Option B ($4$) comes from incomplete reasoning, such as doubling the flour without fully scaling. Option D ($6$) results from setting up the proportion incorrectly.', '{"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}'::jsonb, NULL, 'draft', 1, 45, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XSI2MV', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A line of best fit for a data set is given by $y = 2.5x + 10$, where $x$ represents the number of weeks and $y$ represents the total number of books read. According to this model, how many additional books are read each week?', NULL, '[{"key":"A","text":"$2.5$"},{"key":"B","text":"$10$"},{"key":"C","text":"$12.5$"},{"key":"D","text":"$25$"}]'::jsonb, 'A', NULL, E'The correct answer is A. In the equation $y = 2.5x + 10$, the slope is $2.5$, which represents the rate of change: the number of additional books read per week. Option B ($10$) is the $y$-intercept, representing the starting number of books at week $0$, not the weekly rate. Option C ($12.5$) may result from computing the value at $x = 1$ ($2.5(1) + 10 = 12.5$) and mistaking it for the rate. Option D ($25$) could result from multiplying the slope by $10$.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}'::jsonb, NULL, 'draft', 1, 60, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YEWHEG', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'A line in the $xy$-plane passes through the origin and has a slope of $4$. Which of the following is an equation of this line?', NULL, '[{"key":"A","text":"$y = 4x$"},{"key":"B","text":"$y = x + 4$"},{"key":"C","text":"$y = -4x$"},{"key":"D","text":"$x = 4y$"}]'::jsonb, 'A', NULL, E'The correct answer is A. A line through the origin has a $y$-intercept of $0$, so its equation is $y = mx$ where $m$ is the slope. With a slope of $4$, the equation is $y = 4x$. Option B incorrectly uses $4$ as the $y$-intercept rather than the slope. Option C uses the wrong sign for the slope. Option D reverses the relationship between $x$ and $y$.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}'::jsonb, NULL, 'draft', 1, 30, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
