INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZCXQST', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'grid_in', E'A rectangular box has length $l$, width $w$, and height $h$, where $l = 2w$ and $h = 3w$. If the surface area of the box is $352$, what is the volume of the box?', NULL, '[]'::jsonb, '384', ARRAY['384'], E'The surface area of a rectangular box is $SA = 2(lw + lh + wh)$. Substituting $l = 2w$ and $h = 3w$: $SA = 2(2w \\cdot w + 2w \\cdot 3w + w \\cdot 3w) = 2(2w^2 + 6w^2 + 3w^2) = 2(11w^2) = 22w^2$. Setting $22w^2 = 352$ gives $w^2 = 16$, so $w = 4$. Then $l = 8$ and $h = 12$. The volume is $V = lwh = 8 \\times 4 \\times 12 = 384$. A common error is to find $w$ but then compute only $w^3 = 64$ instead of using the distinct dimensions. Another error is to forget the factor of $2$ in the surface area formula, leading to $w^2 = 32$ and an incorrect result.', NULL, NULL, 'draft', 1, 120, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZEJQNG', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'grid_in', E'If $4(2x - 5) + 6 = 3x + 11$, what is the value of $x$?', NULL, '[]'::jsonb, '5', ARRAY['5'], E'Distribute on the left side: $8x - 20 + 6 = 3x + 11$, which simplifies to $8x - 14 = 3x + 11$. Subtract $3x$ from both sides: $5x - 14 = 11$. Add $14$ to both sides: $5x = 25$. Divide by $5$: $x = 5$.', NULL, NULL, 'draft', 1, 75, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
