INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21SKV7G', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Economists studying consumer behavior have found that people tend to value losses more heavily than equivalent gains, a phenomenon known as loss aversion. In one experiment, participants who were given a coffee mug demanded roughly twice as much to sell it as other participants were willing to pay to buy an identical mug. This asymmetry has significant implications for policy design: programs that frame benefits as avoiding a loss (for example, "you will lose $500 if you don''t insulate your home") tend to be more effective than those that frame the same benefit as a gain ("you will save $500 if you insulate your home"). This suggests that policymakers seeking to encourage specific behaviors would likely be more successful if they ________', '[{"key":"A","text":"increased the monetary value of the incentives they offer to the public."},{"key":"B","text":"eliminated all references to financial outcomes in their communications."},{"key":"C","text":"emphasized what citizens stand to lose by not adopting the desired behavior."},{"key":"D","text":"allowed citizens to choose between gain-framed and loss-framed messages."}]'::jsonb, 'C', NULL, E'The correct answer is C. The passage establishes that loss-framed messages are more effective than gain-framed messages due to loss aversion. The logical completion is that policymakers should emphasize potential losses, aligning with the demonstrated principle. Option A addresses incentive size rather than framing, which is not what the passage discusses. Option B contradicts the passage''s evidence that financial framing matters. Option D misses the point: the passage shows loss framing is superior, not that choice between framings is beneficial.', '{"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}'::jsonb, NULL, 'draft', 1, 90, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23SZGD0', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The city of Tallinn, Estonia, is renowned for its well-preserved medieval architecture. Walking through the Old Town, visitors encounter cobblestone streets and Gothic churches dating back several ______ the town hall, built in the early fifteenth century, remains one of the best-preserved in Northern Europe.', '[{"key":"A","text":"centuries, the"},{"key":"B","text":"centuries the"},{"key":"C","text":"centuries. The"},{"key":"D","text":"centuries, which the"}]'::jsonb, 'C', NULL, E'The correct answer is C. The clause before the blank ("visitors encounter cobblestone streets and Gothic churches dating back several centuries") and the clause after it ("the town hall... remains one of the best-preserved in Northern Europe") are both independent clauses. Two independent clauses cannot be joined by a comma alone, so Option A creates a comma splice. Option B omits all punctuation between the clauses, producing a run-on sentence. Option C correctly uses a period to separate the two independent clauses into distinct sentences. Option D inserts "which" after the comma, but "which the town hall... remains" does not form a grammatically coherent relative clause because "the town hall" provides a second subject where "which" already serves as one.', '{"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}'::jsonb, NULL, 'draft', 1, 60, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23XI1ZL', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the function of the text as a whole?', E'In the fifteenth century, Flemish painters developed a technique of layering thin, translucent glazes of oil paint over an opaque underpainting. Each successive glaze subtly altered the hue and luminosity of the layer beneath, producing an effect of extraordinary depth and richness that was impossible to achieve with a single application of pigment. This method required immense patience, as each layer needed to dry completely before the next could be applied.', '[{"key":"A","text":"To contrast the painting techniques of Flemish artists with those of their Italian contemporaries"},{"key":"B","text":"To argue that Flemish painters were more technically skilled than painters from other traditions"},{"key":"C","text":"To explain a specific painting technique and the visual effect it produced"},{"key":"D","text":"To describe the materials that fifteenth-century painters used in their work"}]'::jsonb, 'C', NULL, E'The correct answer is C. The passage explains how Flemish painters applied translucent glazes over underpaintings and describes the resulting visual effect of ''extraordinary depth and richness.'' This is a description of a technique and its outcome. Option A is wrong because no Italian or other painters are mentioned for comparison. Option B is wrong because the passage does not make any evaluative judgment about Flemish painters'' skill relative to others. Option D captures only a superficial reading; while oil paint is mentioned, the focus is on the technique of layering glazes, not on the materials themselves.', '{"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}'::jsonb, NULL, 'draft', 1, 90, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23Z8LY4', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Recent archaeological discoveries in southern Turkey have pushed back the estimated date for the earliest known temple complexes by several thousand years. The site at Gobekli Tepe, dated to approximately 9500 BCE, features elaborately carved stone pillars arranged in circles, suggesting a degree of social organization previously thought impossible for pre-agricultural societies. ______ some researchers have argued that the construction of such monuments may have actually preceded and even motivated the development of agriculture, rather than the other way around, as scholars had traditionally assumed.', '[{"key":"A","text":"For instance,"},{"key":"B","text":"Granted,"},{"key":"C","text":"On the basis of this evidence,"},{"key":"D","text":"In other words,"}]'::jsonb, 'C', NULL, E'The correct answer is C. The passage presents archaeological evidence (elaborately carved pillars from 9500 BCE in a pre-agricultural society), and the sentence after the blank draws a conclusion from that evidence (monument-building may have preceded agriculture). "On the basis of this evidence," correctly signals that the researchers'' argument is grounded in the findings described. "For instance," (A) would introduce an example, but the sentence after the blank presents an argument, not an illustration. "Granted," (B) would introduce a concession, implying the next sentence acknowledges an opposing point, but the sentence actually advances a bold new claim. "In other words," (D) would signal a restatement of the previous idea, but the sentence after the blank introduces a new causal argument that goes well beyond restating the archaeological findings.', '{"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}'::jsonb, NULL, 'draft', 1, 90, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24FB1VC', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the text as a whole?', E'The Atlantic puffin, sometimes called the ''clown of the sea,'' is easily recognized by its brightly colored beak and distinctive black-and-white plumage. During breeding season, the puffin''s beak becomes even more vibrant, displaying vivid orange, yellow, and blue markings. These small seabirds nest in burrows on coastal cliffs and spend most of their lives at sea.', '[{"key":"A","text":"To describe the physical characteristics and basic habits of a particular seabird"},{"key":"B","text":"To argue that the Atlantic puffin deserves greater conservation attention"},{"key":"C","text":"To compare the Atlantic puffin with other seabird species"},{"key":"D","text":"To explain why the Atlantic puffin is commonly known as the ''clown of the sea''"}]'::jsonb, 'A', NULL, E'The correct answer is A. The passage describes the puffin''s appearance (colored beak, black-and-white plumage, breeding season markings) and its basic habits (nesting in burrows, living at sea), making A the most accurate summary of the text''s function. Option B is wrong because the passage makes no argument about conservation. Option C is wrong because no other seabird species are mentioned or compared. Option D is tempting because the nickname is mentioned, but the passage does not explain the origin of the name; it simply states the nickname and then describes the bird.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}'::jsonb, NULL, 'draft', 1, 60, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
