INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26JE943', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best describes the primary purpose of the text?', E'Historian Mariana Velasco has argued that the standard periodization of the Mexican Revolution into a single arc from 1910 to 1920 obscures the conflict''s fragmented nature. Velasco contends that the revolution was not one movement but several overlapping insurgencies, each with distinct regional leadership, class composition, and ideological commitments. The Zapatista movement in Morelos, for example, pursued agrarian redistribution, while the Constitutionalist faction in the north prioritized institutional reform. Velasco acknowledges that these movements occasionally formed tactical alliances, but she maintains that such cooperation was strategic rather than indicative of shared revolutionary vision. Her framework has been contested by scholars who argue that it underestimates the unifying role of opposition to the Diaz regime.', '[{"key":"A","text":"To present a historian''s argument that the Mexican Revolution is better understood as multiple distinct movements rather than a unified event"},{"key":"B","text":"To compare the military strategies employed by the Zapatista and Constitutionalist factions during the Mexican Revolution"},{"key":"C","text":"To argue that scholars have reached consensus on how to periodize the Mexican Revolution"},{"key":"D","text":"To demonstrate that tactical alliances among revolutionary groups proved they shared a common ideology"}]'::jsonb, 'A', NULL, E'The correct answer is A. The passage is organized around Velasco''s argument that the Mexican Revolution comprised "several overlapping insurgencies" rather than a single movement, and it presents her reasoning and the objections to it. Option B misidentifies the purpose: the Zapatista and Constitutionalist factions are mentioned as examples of ideological diversity, not to compare military strategies. Option C contradicts the passage, which describes ongoing scholarly disagreement about Velasco''s framework. Option D reverses Velasco''s claim: she explicitly states that alliances were "strategic rather than indicative of shared revolutionary vision," so using them to prove shared ideology contradicts the text.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}'::jsonb, NULL, 'draft', 1, 120, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28IJSFD', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In the 1960s, scientists exploring volcanic hot springs in Yellowstone National Park discovered microorganisms thriving in boiling, acidic water. The discovery that certain bacteria can survive in such extreme environments—a finding first reported in ______ has prompted astrobiologists to reconsider the conditions necessary for life to exist on other planets.', '[{"key":"A","text":"1966—has"},{"key":"B","text":"1966, has"},{"key":"C","text":"1966; has"},{"key":"D","text":"1966. Has"}]'::jsonb, 'A', NULL, E'The correct answer is A. The phrase "a finding first reported in 1966" is a parenthetical aside that was opened with an em dash before "a finding." Paired punctuation must match: an em dash must be closed with another em dash. Option A correctly places a closing em dash after "1966," completing the parenthetical and allowing the main clause ("The discovery... has prompted astrobiologists...") to continue. Option B uses a comma, but a comma cannot close a parenthetical that was opened with an em dash; the punctuation marks must be symmetrical. Option C uses a semicolon, which also fails to close the dash-opened parenthetical and would incorrectly signal the start of a new independent clause. Option D uses a period, which would end the sentence after "1966," leaving "Has prompted astrobiologists to reconsider the conditions necessary for life to exist on other planets" as a sentence fragment because it lacks a subject.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}'::jsonb, NULL, 'draft', 1, 90, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28OHVNA', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'When the archaeologist first examined the site in 2019, she discovered several artifacts that ______ to a previously unknown civilization dating back more than three thousand years.', '[{"key":"A","text":"have belonged"},{"key":"B","text":"belongs"},{"key":"C","text":"are belonging"},{"key":"D","text":"had belonged"}]'::jsonb, 'D', NULL, E'The correct answer is D. The sentence establishes a past time frame ("first examined the site in 2019"), and the artifacts'' belonging to the civilization occurred before the archaeologist''s discovery. The past perfect tense ("had belonged") correctly indicates an action completed before another past event. Option A ("have belonged") uses the present perfect, which connects a past action to the present and is inconsistent with the established past narrative frame. Option B ("belongs") is singular present tense, which fails to agree with the plural subject "artifacts" and uses the wrong tense for a past context. Option C ("are belonging") uses the present progressive, which is the wrong tense and also misapplies progressive aspect to the stative verb "belong," which does not normally take the progressive form.', '{"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"correct","error_taxonomy":null}}'::jsonb, NULL, 'draft', 1, 75, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29HDFHL', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The architect Maya Lin, who designed the Vietnam Veterans Memorial when she was only twenty-one years ______ is also known for her large-scale environmental installations exploring the relationship between landscapes and memory.', '[{"key":"A","text":"old"},{"key":"B","text":"old,"},{"key":"C","text":"old;"},{"key":"D","text":"old—"}]'::jsonb, 'B', NULL, E'The correct answer is B. The phrase "who designed the Vietnam Veterans Memorial when she was only twenty-one years old" is a nonrestrictive relative clause providing additional information about Maya Lin. Because this clause is nonrestrictive, it must be set off by a pair of commas: one before "who" (already present in the passage) and one after "old." Option A omits the closing comma, failing to properly set off the nonrestrictive clause. Option C uses a semicolon, which cannot appear in the middle of a sentence to close a nonrestrictive clause; semicolons join independent clauses. Option D uses an em dash, but a nonrestrictive clause opened with a comma must be closed with a comma, not a dash, since the punctuation marks must match.', '{"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}'::jsonb, NULL, 'draft', 1, 75, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29PH30F', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'A researcher hypothesizes that prolonged exposure to microgravity weakens bone density in astronauts. Which finding from the text, if accurate, would most directly support this hypothesis?', E'Space agencies have long monitored the health effects of extended missions aboard the International Space Station. Astronauts typically spend four to six months in orbit, during which they follow rigorous exercise regimens designed to counteract the physiological effects of weightlessness. Despite these measures, medical evaluations conducted upon return have revealed a range of changes, including fluid redistribution toward the head, alterations in cardiovascular function, and measurable reductions in trabecular bone mineral content in the hip and spine. Recovery programs after landing can take several months, and some studies suggest that full restoration of pre-flight bone density is not always achieved.', '[{"key":"A","text":"Astronauts experience fluid redistribution toward the head during spaceflight."},{"key":"B","text":"Exercise regimens aboard the ISS are designed to counteract the effects of weightlessness."},{"key":"C","text":"Medical evaluations showed measurable reductions in trabecular bone mineral content in the hip and spine after missions."},{"key":"D","text":"Astronauts typically spend four to six months in orbit aboard the International Space Station."}]'::jsonb, 'C', NULL, E'The correct answer is C. The hypothesis concerns microgravity weakening bone density, and the finding of measurable reductions in trabecular bone mineral content directly supports this claim by providing evidence of bone loss after prolonged spaceflight. Option A describes fluid redistribution, which relates to a different physiological effect, not bone density. Option B describes countermeasures rather than evidence of bone weakening. Option D states mission duration, which provides context but does not itself demonstrate any effect on bone density.', '{"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}'::jsonb, NULL, 'draft', 1, 90, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2C21SB2', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'What can most reasonably be inferred from the text?', E'For decades, the painted bunting was a common sight at backyard feeders throughout the southeastern United States. In recent years, however, birdwatchers in the region have reported seeing the species far less frequently. Meanwhile, wildlife surveys in Central America, where the painted bunting migrates for winter, have recorded stable or increasing populations of the bird in its wintering habitat.', '[{"key":"A","text":"The painted bunting has become extinct in the southeastern United States."},{"key":"B","text":"The decline in sightings in the southeastern United States is likely not caused by an overall decrease in the species'' total population."},{"key":"C","text":"Birdwatchers in the southeastern United States have become less interested in observing painted buntings."},{"key":"D","text":"Central American wildlife surveys use more accurate counting methods than surveys conducted in the United States."}]'::jsonb, 'B', NULL, E'The correct answer is B. The passage states that sightings have decreased in the southeastern U.S. but populations in Central America remain stable or are increasing. If the species were declining overall, one would expect decreases in both locations. Because the wintering population is healthy, the reduced sightings in the U.S. are likely attributable to something other than a total population decline. Option A overstates the situation: fewer sightings does not mean extinction. Option C introduces an unsupported claim about birdwatcher interest. Option D makes a claim about survey methodology that is not addressed in the passage.', '{"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}'::jsonb, NULL, 'draft', 1, 60, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CH2C2V', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Although the initial results of the clinical trial were promising and suggested that the new treatment could reduce symptoms by as much as forty ______ the researchers cautioned that a larger, multi-site study would be necessary before the drug could receive regulatory approval.', '[{"key":"A","text":"percent; the"},{"key":"B","text":"percent the"},{"key":"C","text":"percent, the"},{"key":"D","text":"percent. The"}]'::jsonb, 'C', NULL, E'The correct answer is C. The sentence begins with the subordinating conjunction "Although," which makes the entire first clause ("Although the initial results... forty percent") a dependent clause. A dependent introductory clause must be followed by a comma before the independent clause that completes the sentence. Option A uses a semicolon, but semicolons are used to join two independent clauses; a dependent clause beginning with "Although" cannot precede a semicolon. Option B omits punctuation entirely, creating a difficult-to-parse run-on. Option D places a period after "percent," but "Although the initial results of the clinical trial were promising and suggested that the new treatment could reduce symptoms by as much as forty percent" is a sentence fragment because it is a dependent clause that cannot stand on its own. The length and complexity of the dependent clause is the primary difficulty here, as students may lose track of the opening "Although" and mistake the first clause for an independent one.', '{"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}'::jsonb, NULL, 'draft', 1, 90, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FPGD78', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'While researching the applications of CRISPR gene-editing technology, a student has taken the following notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2G7QF7P', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'A literary critic argues that the novel''s narrator is unreliable because the narrator''s account of events is contradicted by details embedded elsewhere in the text. Which quotation from the novel would most effectively support the critic''s argument?', E'In Elara Voss''s 2018 novel The Divided House, the first-person narrator, Thomas, repeatedly insists that his relationship with his brother was harmonious throughout their childhood. Thomas describes shared adventures, mutual loyalty, and an unbreakable bond. However, scholars have noted that letters, diary entries, and dialogue from other characters woven into the narrative present a markedly different picture. These embedded documents suggest frequent conflicts, periods of estrangement, and deep-seated resentment that Thomas never directly acknowledges. Voss has stated in interviews that this tension between the narrator''s claims and the textual evidence was deliberately constructed.', '[{"key":"A","text":"Thomas states, \\"My brother and I were inseparable; every summer we explored the woods behind our house together, never once quarreling.\\""},{"key":"B","text":"A letter from Thomas''s mother reads, \\"I worry about the boys constantly fighting. Thomas refuses to speak to his brother for weeks at a time.\\""},{"key":"C","text":"Thomas reflects, \\"Looking back, I realize childhood is never as simple as we remember it, though the good outweighed the bad.\\""},{"key":"D","text":"The novel''s epilogue describes Thomas visiting his brother''s home for a holiday dinner."}]'::jsonb, 'B', NULL, E'The correct answer is B. The critic''s argument depends on showing that the narrator''s account is contradicted by other textual evidence. The mother''s letter directly contradicts Thomas''s claim of a harmonious relationship by describing constant fighting and prolonged estrangement. Option A is Thomas''s own narration, which illustrates his claims but does not contradict them, so it cannot demonstrate unreliability. Option C shows Thomas making a general, somewhat qualified reflection but does not provide a specific contradiction from an independent source. Option D describes a neutral event that neither supports nor undermines Thomas''s account of their childhood relationship.', '{"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}'::jsonb, NULL, 'draft', 1, 120, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2H4D1Q5', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'Historians have long debated whether the general''s decision to withdraw was a ______ retreat or a calculated maneuver designed to lure the opposing forces into overextending their supply lines. Recent archival discoveries suggest the latter interpretation is closer to the truth.', '[{"key":"A","text":"provisional"},{"key":"B","text":"strategic"},{"key":"C","text":"precipitous"},{"key":"D","text":"cowardly"}]'::jsonb, 'C', NULL, E'The correct answer is C. The sentence sets up a contrast between two interpretations: the blank must describe a retreat that is the opposite of ''a calculated maneuver.'' ''Precipitous'' means hasty and without careful deliberation, which creates the precise contrast needed. Option A, ''provisional,'' means temporary or interim, which describes the duration of the retreat rather than its character as planned or unplanned -- the debate is about deliberation, not duration, so ''provisional'' does not fit the required contrast. Option B, ''strategic,'' would eliminate the contrast entirely, since a strategic retreat and a calculated maneuver are essentially synonymous. Option D, ''cowardly,'' is too pejorative for the neutral, scholarly register of the passage, and the debate is about planning versus haste, not courage versus fear.', '{"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}'::jsonb, NULL, 'draft', 1, 120, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2I02DNR', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'The poet''s latest collection has been praised for its ______ language. Critics note that every word feels carefully chosen, with no unnecessary or wasteful phrasing cluttering the verses.', '[{"key":"A","text":"economical"},{"key":"B","text":"elaborate"},{"key":"C","text":"archaic"},{"key":"D","text":"ambiguous"}]'::jsonb, 'A', NULL, E'The correct answer is A. The passage states that every word feels ''carefully chosen'' with ''no unnecessary or wasteful phrasing,'' which directly describes language that is economical -- concise and efficient. Option B, ''elaborate,'' means ornate or detailed, which contradicts the emphasis on avoiding excess. Option C, ''archaic,'' means old-fashioned, which is not supported by any detail in the passage. Option D, ''ambiguous,'' means unclear or open to multiple interpretations, which conflicts with the idea of precisely chosen words.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}'::jsonb, NULL, 'draft', 1, 60, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2I2YRUW', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'In the early twentieth century, physicists expected that the laws governing large-scale objects would also apply at the subatomic level. Experiments with electrons and photons, however, revealed behavior that classical mechanics could not explain: particles sometimes acted as waves, and their properties seemed to depend on observation. ______ Werner Heisenberg proposed the uncertainty principle, which established that certain pairs of physical properties, such as position and momentum, cannot both be precisely measured at the same time.', '[{"key":"A","text":"Nevertheless,"},{"key":"B","text":"To address these puzzling findings,"},{"key":"C","text":"In contrast,"},{"key":"D","text":"Similarly,"}]'::jsonb, 'B', NULL, E'The correct answer is B. The preceding sentences describe puzzling experimental results that classical mechanics could not explain, and the following sentence introduces Heisenberg''s uncertainty principle as a response to those results. "To address these puzzling findings," correctly signals that Heisenberg''s work was motivated by the anomalous observations. "Nevertheless," (A) implies that the uncertainty principle was proposed despite the experimental findings, reversing the logical relationship. "In contrast," (C) incorrectly suggests opposition between the findings and Heisenberg''s response, when his principle actually built upon them. "Similarly," (D) misreads the relationship as a parallel rather than a response to a problem.', '{"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}'::jsonb, NULL, 'draft', 1, 75, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2L8J5NR', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'Although the diplomat''s public statements were notably ______, her private memoranda reveal a sharp, incisive mind that left no detail unexamined. Colleagues often remarked on the contrast between her reserved public persona and her thorough behind-the-scenes analysis.', '[{"key":"A","text":"meticulous"},{"key":"B","text":"guarded"},{"key":"C","text":"eloquent"},{"key":"D","text":"dismissive"}]'::jsonb, 'B', NULL, E'The correct answer is B. The passage establishes a contrast between the diplomat''s public reserve and her private thoroughness. ''Guarded'' means cautious and restrained, which aligns with ''reserved public persona'' and stands in clear opposition to the ''sharp, incisive'' private analysis. Option A, ''meticulous,'' means careful and thorough, which actually describes the private side of the contrast, not the public statements. Option C, ''eloquent,'' means fluent and persuasive in speech, but the passage emphasizes restraint, not rhetorical skill. Option D, ''dismissive,'' implies contemptuous disregard, which is far more negative than anything the passage supports.', '{"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}'::jsonb, NULL, 'draft', 1, 90, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OPHW3D', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'While researching the history of public libraries in the United States, a student has taken the following notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2V03ZIW', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Marine biologists have long understood that coral reefs support extraordinary biodiversity. A single reef system can host thousands of species of fish, invertebrates, and algae. ______ reefs also provide critical economic benefits to coastal communities, supporting fishing industries and tourism that generate billions of dollars annually.', '[{"key":"A","text":"In addition,"},{"key":"B","text":"However,"},{"key":"C","text":"For example,"},{"key":"D","text":"Consequently,"}]'::jsonb, 'A', NULL, E'The correct answer is A. The sentence before the blank discusses biodiversity, and the sentence after the blank introduces a new, additional benefit (economic value). "In addition," correctly signals that a second point is being added. "However," (B) incorrectly implies a contrast between the two ideas, when both are positive attributes of reefs. "For example," (C) implies the economic benefits illustrate the biodiversity point, but they are a separate category of benefit. "Consequently," (D) implies a cause-and-effect relationship, but economic benefits are not a consequence of biodiversity.', '{"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}'::jsonb, NULL, 'draft', 1, 60, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
