INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2W4VWNO', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'The researcher''s findings ______ the long-held assumption that early agricultural societies were necessarily sedentary. By documenting seasonal migration patterns among ancient farming communities in the Levant, she demonstrated that cultivation and mobility were not mutually exclusive.', '[{"key":"A","text":"substantiated"},{"key":"B","text":"underscored"},{"key":"C","text":"acknowledged"},{"key":"D","text":"undermined"}]'::jsonb, 'D', NULL, E'The correct answer is D. The researcher showed that farming communities migrated seasonally, which directly contradicts the assumption that agricultural societies were ''necessarily sedentary.'' ''Undermined'' means weakened or challenged, which precisely captures this relationship. Option A, ''substantiated,'' means confirmed or proved, which is the opposite of what the passage describes. Option B, ''underscored,'' means emphasized or highlighted, which would imply the researcher supported the assumption rather than challenged it. Option C, ''acknowledged,'' means recognized the existence of something, which is too neutral; the researcher did not merely recognize the assumption but actively produced evidence against it.', '{"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}'::jsonb, NULL, 'draft', 1, 120, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WGP12G', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'What can most reasonably be inferred about the relationship between the two studies discussed in the text?', E'A 2015 study by Chen and Alvarez found that bilingual children performed significantly better than monolingual peers on tasks requiring them to switch between different rule sets, a cognitive ability known as task-switching. The researchers attributed this advantage to the daily practice bilinguals get in suppressing one language while using another. A 2020 study by Hartmann, however, tested a larger and more socioeconomically diverse sample and found no statistically significant difference in task-switching performance between bilingual and monolingual children. Hartmann''s team controlled for variables such as parental education, household income, and hours of formal instruction that Chen and Alvarez had not accounted for in their original design.', '[{"key":"A","text":"Hartmann''s study confirmed Chen and Alvarez''s findings using a more rigorous methodology."},{"key":"B","text":"Hartmann''s results suggest that the bilingual advantage observed by Chen and Alvarez may have been attributable to socioeconomic factors rather than bilingualism itself."},{"key":"C","text":"Both studies agree that bilingualism provides cognitive benefits beyond task-switching ability."},{"key":"D","text":"Chen and Alvarez deliberately excluded socioeconomically diverse participants from their sample."}]'::jsonb, 'B', NULL, E'The correct answer is B. Hartmann''s study controlled for socioeconomic variables that Chen and Alvarez did not account for and found no significant bilingual advantage. This implies that the advantage Chen and Alvarez observed may have been driven by socioeconomic differences between their bilingual and monolingual groups rather than by bilingualism itself. Option A is incorrect because Hartmann''s study contradicted, not confirmed, the earlier findings. Option C is unsupported: neither study is described as examining cognitive benefits beyond task-switching. Option D overstates the case: the passage says Chen and Alvarez did not control for socioeconomic diversity, not that they deliberately excluded diverse participants.', '{"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}'::jsonb, NULL, 'draft', 1, 120, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WH1WY6', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'In the 1970s, psychologist Elizabeth Loftus conducted experiments demonstrating that eyewitness memory is far less reliable than courts had assumed. By introducing misleading information after an event, Loftus showed that participants would incorporate false details into their recollections and report them with high confidence. Her work challenged the long-standing legal presumption that confident testimony is accurate testimony. While some critics argued that laboratory conditions do not replicate the stress of real crimes, subsequent field studies largely corroborated Loftus''s central findings, prompting reforms in how police lineups and witness interviews are conducted.', '[{"key":"A","text":"Elizabeth Loftus proved that all eyewitness testimony is unreliable and should be excluded from court proceedings."},{"key":"B","text":"Research by Loftus and others revealed significant flaws in eyewitness memory, ultimately influencing changes in legal procedures."},{"key":"C","text":"Critics of Loftus''s research successfully demonstrated that laboratory experiments cannot be applied to real criminal cases."},{"key":"D","text":"Police departments independently discovered problems with eyewitness testimony before Loftus published her findings."}]'::jsonb, 'B', NULL, E'The correct answer is B. The passage traces Loftus''s research showing eyewitness memory is unreliable, notes that field studies corroborated her findings, and states that reforms followed in police lineups and interviews. Option B captures both the research findings and their practical impact. Option A overstates the conclusion: Loftus showed memory is less reliable than assumed, not that all testimony should be excluded. Option C misrepresents the critics'' role; the passage states field studies "largely corroborated" Loftus, meaning the critics did not successfully undermine her work. Option D introduces a claim about independent police discovery that appears nowhere in the passage.', '{"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}'::jsonb, NULL, 'draft', 1, 90, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WOMVGV', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Marine biologists studying coral reefs in the Pacific Ocean have documented a surprising recovery in areas previously damaged by bleaching events. After water temperatures returned to normal levels in 2021, several reef systems showed new coral growth within eighteen months. The researchers noted that species diversity in recovering areas was comparable to that of undamaged reefs nearby, suggesting that coral ecosystems may be more resilient than earlier models predicted.', '[{"key":"A","text":"Coral reefs in the Pacific Ocean are the most biodiverse marine ecosystems on Earth."},{"key":"B","text":"Recent observations indicate that damaged coral reefs can recover more effectively than scientists previously expected."},{"key":"C","text":"Water temperature is the sole factor determining whether coral reefs survive bleaching events."},{"key":"D","text":"Marine biologists have shifted their research focus from reef damage to reef preservation strategies."}]'::jsonb, 'B', NULL, E'The correct answer is B. The passage describes how coral reefs damaged by bleaching showed surprising recovery, with species diversity comparable to undamaged reefs, leading researchers to conclude that coral ecosystems "may be more resilient than earlier models predicted." This directly supports the idea that recovery has exceeded prior expectations. Option A introduces a claim about biodiversity rankings not found in the passage. Option C overstates the role of temperature by calling it the "sole factor," which the passage does not assert. Option D fabricates a shift in research focus that the passage does not mention.', '{"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}'::jsonb, NULL, 'draft', 1, 60, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WU73CO', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the overall structure of the text?', E'When the philosopher Hannah Arendt observed the 1961 trial of Adolf Eichmann in Jerusalem, she expected to encounter a monster. Instead, she found a disturbingly ordinary bureaucrat who seemed incapable of independent thought. Eichmann did not display fanatical hatred; he displayed an unsettling eagerness to follow orders and a total inability to consider the moral implications of his actions. Arendt''s phrase ''the banality of evil'' -- the idea that great atrocities can be committed by unremarkable people who simply fail to think -- emerged from this observation and has since become one of the most debated concepts in moral philosophy.', '[{"key":"A","text":"It summarizes a philosopher''s career and explains her most famous contribution to moral theory"},{"key":"B","text":"It presents an expectation, describes how that expectation was contradicted by observation, and introduces a concept that arose from the contradiction"},{"key":"C","text":"It describes a historical event and evaluates the accuracy of a philosophical claim made about that event"},{"key":"D","text":"It presents two competing interpretations of a historical figure and argues in favor of one"}]'::jsonb, 'B', NULL, E'The correct answer is B. The text follows a clear three-part structure: Arendt expected a ''monster'' (expectation), she instead found an ''ordinary bureaucrat'' (contradiction), and from this gap between expectation and reality the concept of ''the banality of evil'' emerged (concept introduced). Option A is wrong because the passage discusses only one observation, not a career summary. Option C is wrong because the text does not evaluate whether Arendt''s concept is accurate; it presents the concept without judging it. Option D is wrong because the text does not present two competing interpretations; it presents Arendt''s single, unified observation and the concept she drew from it.', '{"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}'::jsonb, NULL, 'draft', 1, 120, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Y1F5QM', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'A student claims that the city''s tree-planting initiative has had measurable environmental benefits. Which finding, if true, would most directly support this claim?', E'In 2019, the city of Riverside launched an urban reforestation program, planting over 10,000 trees along streets and in public parks. City officials stated that the program aimed to reduce summer temperatures in heavily paved neighborhoods and improve local air quality. Residents in affected neighborhoods have generally expressed approval of the initiative, citing increased shade and improved appearance of their streets.', '[{"key":"A","text":"A survey found that 85% of Riverside residents consider tree-lined streets more visually appealing than streets without trees."},{"key":"B","text":"Air quality monitoring stations in neighborhoods with new trees recorded a 12% decrease in particulate matter concentrations between 2019 and 2023."},{"key":"C","text":"The city allocated $2.4 million from its general fund to cover the costs of purchasing and planting the trees."},{"key":"D","text":"Several neighboring cities announced similar reforestation plans after observing Riverside''s program."}]'::jsonb, 'B', NULL, E'The correct answer is B. The claim is about measurable environmental benefits, and a documented 12% decrease in particulate matter is a direct, quantifiable environmental improvement linked to the tree-planting areas. Option A addresses aesthetic appeal, not environmental benefit. Option C describes funding, which is relevant to cost but not to environmental outcomes. Option D describes other cities'' responses, which does not measure any environmental effect of Riverside''s program.', '{"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}'::jsonb, NULL, 'draft', 1, 60, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YMBGDG', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The collection of rare manuscripts housed in the university''s special archives ______ an invaluable resource for scholars studying medieval European literature and the social history of the period.', '[{"key":"A","text":"remain"},{"key":"B","text":"remains"},{"key":"C","text":"are remaining"},{"key":"D","text":"have remained"}]'::jsonb, 'B', NULL, E'The correct answer is B. The subject of the sentence is "collection," which is singular. The prepositional phrase "of rare manuscripts housed in the university''s special archives" modifies "collection" but does not change the number of the subject. A singular subject requires a singular verb: "remains." Option A ("remain") is plural and does not agree with the singular subject "collection." Option C ("are remaining") uses the plural form "are" and also places the stative verb "remain" in the progressive aspect, which is non-standard. Option D ("have remained") uses the plural auxiliary "have" instead of the singular "has."', '{"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}'::jsonb, NULL, 'draft', 1, 60, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZSHIDZ', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'After reviewing the results of the annual assessment, the committee recommended that the university ______ its admissions policy to place greater emphasis on demonstrated community involvement and leadership experience rather than standardized test scores alone.', '[{"key":"A","text":"revises"},{"key":"B","text":"revise"},{"key":"C","text":"will revise"},{"key":"D","text":"had revised"}]'::jsonb, 'B', NULL, E'The correct answer is B. The verb "recommended" triggers the mandative subjunctive in the "that" clause that follows it. In the subjunctive mood, the verb takes its base form ("revise") regardless of the subject''s number. Option A ("revises") uses the third-person singular indicative form, which would ordinarily agree with the singular subject "university" but is incorrect here because the subjunctive, not the indicative, is required after verbs of recommendation, suggestion, and demand. This is the primary trap: students who rely on subject-verb agreement instincts may choose the indicative form. Option C ("will revise") incorrectly uses the future indicative; the subjunctive construction does not permit modal auxiliaries. Option D ("had revised") uses the past perfect tense, which would indicate the revision already occurred before the recommendation, contradicting the meaning of the sentence.', '{"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}'::jsonb, NULL, 'draft', 1, 90, false, '{"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-07-20"}'::jsonb, '{"model":"claude","generation_date":"2026-07-20","prompt_version":"questions_governance_v1"}'::jsonb);
